    return entity;
  }

  async getById(id) {
    return noteActivityCache.remember(`id:${id}`, 120, async () => {
      const entity = await noteActivityRepo.findById(id);
      if (!entity) throw ApiError.notFound('NoteActivity not found');
      return entity;
