Set-Content -Path 'src\modules\products\domain\repositories\product.repository.js' -Value @'
const BaseRepository = require('../../../../core/BaseRepository');
const Product = require('../../infrastructure/models/product.model');

class ProductRepository extends BaseRepository {
  constructor() {
    super(Product);
  }

  async findBySku(sku) {
    return this.model.findOne({ sku: sku.toUpperCase() });
  }

  async findLowStock(threshold = 5) {
    return this.model.find({ stock: { $lte: threshold }, isActive: true });
  }

  async decrementStock(id, quantity, session = null) {
    return this.model.findOneAndUpdate(
      { _id: id, stock: { $gte: quantity } }, // guards against negative stock
      { $inc: { stock: -quantity } },
      { new: true, session }
    );
  }

  async search(term, options) {
    return this.find({ $text: { $search: term }, isActive: true }, options);
  }
}

// Repositories are stateless-ish, safe to export a singleton
module.exports = new ProductRepository();
'@

Set-Content -Path 'src\modules\products\events\product.events.js' -Value @'
const eventBus = require('../../../core/eventBus');

/**
 * Events this module PUBLISHES. Other modules (analytics, notification,
 * audit, webhook...) can subscribe without products.module knowing they exist.
 */
const PRODUCT_EVENTS = {
  CREATED: 'product.created',
  UPDATED: 'product.updated',
  DELETED: 'product.deleted',
  LOW_STOCK: 'product.low_stock',
};

function publishProductCreated(product) {
  eventBus.publish(PRODUCT_EVENTS.CREATED, { productId: product._id, sku: product.sku });
}

function publishProductUpdated(product) {
  eventBus.publish(PRODUCT_EVENTS.UPDATED, { productId: product._id });
}

function publishProductDeleted(productId) {
  eventBus.publish(PRODUCT_EVENTS.DELETED, { productId });
}

function publishLowStock(product) {
  eventBus.publish(PRODUCT_EVENTS.LOW_STOCK, {
    productId: product._id,
    sku: product.sku,
    stock: product.stock,
  });
}

/**
 * Events this module LISTENS to from other modules would be wired here too,
 * e.g. eventBus.subscribe('order.created', handleOrderCreated) to decrement stock.
 * Left out here since 'orders' module doesn't exist yet in this scaffold —
 * this is exactly the seam where that integration would go.
 */

module.exports = {
  PRODUCT_EVENTS,
  publishProductCreated,
  publishProductUpdated,
  publishProductDeleted,
  publishLowStock,
};
'@

Set-Content -Path 'src\modules\products\infrastructure\models\product.model.js' -Value @'
const mongoose = require('mongoose');
const { getConnection } = require('../../../../core/database');

const productSchema = new mongoose.Schema(
  {
    name: { type: String, required: true, trim: true },
    sku: { type: String, required: true, unique: true, uppercase: true, trim: true },
    price: { type: Number, required: true, min: 0 },
    stock: { type: Number, required: true, min: 0, default: 0 },
    category: { type: String, index: true },
    isActive: { type: Boolean, default: true },
  },
  { timestamps: true }
);

productSchema.index({ name: 'text', sku: 'text' });

// 'products_db' -> its own logical database. Change to 'main' if you want
// every module sharing one physical DB for now (still fine, still isolated logically).
const conn = getConnection(process.env.PRODUCTS_DB_NAME || 'products_db');

module.exports = conn.model('Product', productSchema);
'@

Set-Content -Path 'src\modules\products\jobs\product.jobs.js' -Value @'
const { Queue } = require('bullmq');

const connection = {
  host: process.env.REDIS_HOST || 'localhost',
  port: process.env.REDIS_PORT || 6379,
};

const productQueue = new Queue('products', { connection });

/**
 * Example: queue a search-index rebuild instead of doing it inline
 * on every write. Call this from the service when needed:
 *   const { queueReindex } = require('../../jobs/product.jobs');
 *   await queueReindex(product._id);
 */
async function queueReindex(productId) {
  await productQueue.add('reindex', { productId }, { attempts: 3, backoff: { type: 'exponential', delay: 2000 } });
}

module.exports = { productQueue, queueReindex };
'@

Set-Content -Path 'src\modules\storefront\index.js' -Value @'
const express = require('express');
const router = express.Router();

/**
 * This is a NAMESPACE, not a module with its own model/service.
 * It only aggregates its sub-modules' routers below. Each one is a
 * fully independent module with its own model, repository, service,
 * events and cache — they do NOT import each other directly, only
 * communicate via the event bus.
 */
router.use('/platform-delivery-agent', require('./platformDeliveryAgent').router);
router.use('/section-template', require('./sectionTemplate').router);
router.use('/smart-rule', require('./smartRule').router);
router.use('/storefront-cart', require('./storefrontCart').router);
router.use('/storefront-cart-item', require('./storefrontCartItem').router);
router.use('/storefront-coupon', require('./storefrontCoupon').router);
router.use('/storefront-customer', require('./storefrontCustomer').router);
router.use('/storefront-customer-address', require('./storefrontCustomerAddress').router);
router.use('/storefront-delivery-agent', require('./storefrontDeliveryAgent').router);
router.use('/storefront-form-submission', require('./storefrontFormSubmission').router);
router.use('/storefront-layout', require('./storefrontLayout').router);
router.use('/storefront-order', require('./storefrontOrder').router);
router.use('/storefront-page', require('./storefrontPage').router);
router.use('/storefront-page-snapshot', require('./storefrontPageSnapshot').router);
router.use('/storefront-session', require('./storefrontSession').router);
router.use('/storefront-wishlist', require('./storefrontWishlist').router);

module.exports = { router };
