cat > 'scripts/make-module.js' << 'APEX_EOF_MARKER'
#!/usr/bin/env node
/**
 * Module generator.
 *
 * Flat module:
 *   node scripts/make-module.js products
 *   -> src/modules/products/  (mount in gateway as /products)
 *
 * Nested sub-module under a parent namespace (e.g. HRMS):
 *   node scripts/make-module.js hrms/attendance
 *   node scripts/make-module.js hrms/employee
 *   node scripts/make-module.js hrms/leave
 *   -> src/modules/hrms/attendance/  (full independent module)
 *   -> src/modules/hrms/employee/    (full independent module)
 *   -> src/modules/hrms/index.js     (auto-created/updated aggregator,
 *                                      mounts each sub-module's router)
 *
 * Then mount ONLY the top-level namespace in gateway:
 *   router.use('/hrms', require('../modules/hrms').router);
 * -> exposes /hrms/attendance/*, /hrms/employee/*, /hrms/leave/*, etc.
 *
 * Nesting can go deeper too (hrms/payroll/salary) — each level gets its
 * own aggregator index.js automatically.
 */
const fs = require('fs');
const path = require('path');
const templates = require('./templates/moduleTemplates');

const rawArg = process.argv[2];

if (!rawArg) {
  console.error('Usage: node scripts/make-module.js <moduleName>');
  console.error('Examples:');
  console.error('  node scripts/make-module.js products');
  console.error('  node scripts/make-module.js hrms/attendance');
  process.exit(1);
}

function toPascalCase(str) {
  return str
    .replace(/[-_]+/g, ' ')
    .split(' ')
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join('');
}

function toCamelCase(str) {
  const pascal = toPascalCase(str);
  return pascal.charAt(0).toLowerCase() + pascal.slice(1);
}

// Split "hrms/attendance" -> ['hrms', 'attendance'], normalize each segment
const segments = rawArg
  .split('/')
  .filter(Boolean)
  .map((seg) => toCamelCase(seg));

if (segments.length === 0) {
  console.error('Invalid module name.');
  process.exit(1);
}

const leaf = segments[segments.length - 1];
const parentSegments = segments.slice(0, -1); // [] for flat modules

const pascal = toPascalCase(leaf);
const camel = leaf;
const kebab = camel.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
const upper = camel.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase();

// --- compute core-relative import paths based on nesting depth ---
// distance (in directories) from a file to src/core:
//   1 (the "modules" dir) + segments.length (module path depth) + subfolderDepth
const moduleDepth = segments.length;
const upPath = (subfolderDepth) => '../'.repeat(1 + moduleDepth + subfolderDepth) + 'core';

const names = {
  pascal,
  camel,
  kebab,
  upper,
  corePath2: upPath(2), // controllers/routes/validators/services/repositories/models
  corePath1: upPath(1), // events/cache
};

const modulesRoot = path.join(__dirname, '..', 'src', 'modules');
const moduleRoot = path.join(modulesRoot, ...segments);

if (fs.existsSync(moduleRoot)) {
  console.error(`Module "${segments.join('/')}" already exists at ${moduleRoot}`);
  process.exit(1);
}

const structure = [
  ['api/controllers', `${camel}.controller.js`, templates.controller],
  ['api/routes', `${camel}.routes.js`, templates.routes],
  ['api/validators', `${camel}.validator.js`, templates.validator],
  ['application/services', `${camel}.service.js`, templates.service],
  ['domain/repositories', `${camel}.repository.js`, templates.repository],
  ['infrastructure/models', `${camel}.model.js`, templates.model],
  ['events', `${camel}.events.js`, templates.events],
  ['cache', `${camel}.cache.js`, templates.cache],
  ['', 'index.js', templates.moduleIndex],
];

const emptyFolders = ['jobs', 'tests'];

structure.forEach(([dir, filename, templateFn]) => {
  const fullDir = path.join(moduleRoot, dir);
  fs.mkdirSync(fullDir, { recursive: true });
  fs.writeFileSync(path.join(fullDir, filename), templateFn(names));
});

emptyFolders.forEach((dir) => {
  const fullDir = path.join(moduleRoot, dir);
  fs.mkdirSync(fullDir, { recursive: true });
  fs.writeFileSync(path.join(fullDir, '.gitkeep'), '');
});

console.log(`✔ Module "${segments.join('/')}" created at src/modules/${segments.join('/')}`);

// --- maintain parent aggregator index.js files, bottom-up ---
// e.g. for hrms/attendance -> ensure src/modules/hrms/index.js exists and
// includes an entry for "attendance".
//
// Children are determined by SCANNING THE FILESYSTEM (any subdirectory that
// itself has an index.js is a child module), not by parsing the previous
// index.js's text. This is deliberate: regex-parsing generated code to infer
// state is fragile (a kebab-case URL segment like "/attendance-daily" breaks
// a naive \w+ pattern) and silently drops entries. Scanning disk state is
// the single source of truth and self-heals even if a previous run left an
// aggregator in a bad state.
function scanChildren(dirPath) {
  if (!fs.existsSync(dirPath)) return [];
  return fs
    .readdirSync(dirPath, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((name) => fs.existsSync(path.join(dirPath, name, 'index.js')))
    .sort();
}

function ensureParentAggregator(parentSegs) {
  if (parentSegs.length === 0) return; // no parent namespace, nothing to aggregate

  const parentDir = path.join(modulesRoot, ...parentSegs);
  const parentIndexPath = path.join(parentDir, 'index.js');
  fs.mkdirSync(parentDir, { recursive: true });

  const children = scanChildren(parentDir);

  fs.writeFileSync(parentIndexPath, templates.parentAggregatorIndex(children));
  console.log(`  ↳ updated aggregator: src/modules/${parentSegs.join('/')}/index.js (${children.length} children)`);

  // Recurse in case of deeper nesting (e.g. a/b/c -> also ensure a/index.js aggregates b)
  if (parentSegs.length > 1) {
    ensureParentAggregator(parentSegs.slice(0, -1));
  }
}

ensureParentAggregator(parentSegments);

console.log('');
if (parentSegments.length > 0) {
  const topLevel = parentSegments[0];
  console.log('Next step — mount the top-level namespace ONCE in src/gateway/routes.js:');
  console.log(`  router.use('/${topLevel}', require('../modules/${topLevel}').router);`);
  console.log(`(sub-modules are auto-exposed under /${topLevel}/${kebab}, etc. — no extra gateway line needed per sub-module)`);
} else {
  console.log('Next step — mount it in src/gateway/routes.js:');
  console.log(`  router.use('/${kebab}', require('../modules/${camel}').router);`);
}
APEX_EOF_MARKER

cat > 'scripts/repair-aggregators.js' << 'APEX_EOF_MARKER'
#!/usr/bin/env node
/**
 * One-time repair: rebuild every namespace aggregator index.js in
 * src/modules from actual filesystem state, bottom-up. Fixes any
 * aggregator that was corrupted by the old regex-based children detection.
 */
const fs = require('fs');
const path = require('path');
const templates = require('./templates/moduleTemplates');

const modulesRoot = path.join(__dirname, '..', 'src', 'modules');

function scanChildren(dirPath) {
  return fs
    .readdirSync(dirPath, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((name) => fs.existsSync(path.join(dirPath, name, 'index.js')))
    .sort();
}

// A directory is a NAMESPACE (aggregator) if at least one of its
// subdirectories itself has an index.js. Leaf entity modules only have
// api/application/domain/infrastructure/events/cache/jobs/tests - none of
// which have their own index.js - so they're correctly left untouched.
function isNamespace(dirPath) {
  if (!fs.existsSync(dirPath)) return false;
  return scanChildren(dirPath).length > 0;
}

function walkAndRepair(dirPath, relPath) {
  const entries = fs.readdirSync(dirPath, { withFileTypes: true }).filter((e) => e.isDirectory());

  // Repair children first (bottom-up), so nested namespaces are fixed
  // before we decide whether THIS directory is a namespace.
  entries.forEach((entry) => {
    walkAndRepair(path.join(dirPath, entry.name), path.join(relPath, entry.name));
  });

  if (isNamespace(dirPath)) {
    const children = scanChildren(dirPath);
    fs.writeFileSync(path.join(dirPath, 'index.js'), templates.parentAggregatorIndex(children));
    console.log(`repaired: src/modules/${relPath || '.'}/index.js  (${children.length} children: ${children.join(', ')})`);
  }
}

const topLevel = fs.readdirSync(modulesRoot, { withFileTypes: true }).filter((e) => e.isDirectory());
topLevel.forEach((entry) => {
  walkAndRepair(path.join(modulesRoot, entry.name), entry.name);
});

console.log('\nRepair complete.');
APEX_EOF_MARKER

cat > 'scripts/templates/moduleTemplates.js' << 'APEX_EOF_MARKER'
/**
 * Each function returns the file content for one file in a generated module.
 *
 * `names` = {
 *   pascal, camel, kebab, upper   -> derived from the LEAF segment (e.g. "attendance")
 *   corePath2                     -> relative path to src/core from a file 2 levels
 *                                    deep inside the module (controllers, routes,
 *                                    validators, services, repositories, models)
 *   corePath1                     -> relative path to src/core from a file 1 level
 *                                    deep inside the module (events, cache)
 * }
 *
 * corePath1/2 are computed by the generator based on module nesting depth, so this
 * SAME template produces correct imports whether the module is
 *   src/modules/products/...            (depth 1)
 * or
 *   src/modules/hrms/attendance/...     (depth 2, nested under a parent namespace)
 */

const model = ({ pascal, camel, corePath2 }) => `const mongoose = require('mongoose');
const { getConnection } = require('${corePath2}/database');

const ${camel}Schema = new mongoose.Schema(
  {
    name: { type: String, required: true, trim: true },
    isActive: { type: Boolean, default: true },
    // TODO: add ${pascal}-specific fields here
  },
  { timestamps: true }
);

const conn = getConnection(process.env.${camel.toUpperCase()}_DB_NAME || '${camel}_db');

module.exports = conn.model('${pascal}', ${camel}Schema);
`;

const repository = ({ pascal, camel, corePath2 }) => `const BaseRepository = require('${corePath2}/BaseRepository');
const ${pascal} = require('../../infrastructure/models/${camel}.model');

class ${pascal}Repository extends BaseRepository {
  constructor() {
    super(${pascal});
  }

  // TODO: add ${pascal}-specific query methods here, e.g.
  // async findByCode(code) { return this.model.findOne({ code }); }
}

module.exports = new ${pascal}Repository();
`;

const cache = ({ camel, corePath1 }) => `const CacheService = require('${corePath1}/cache');

module.exports = new CacheService('${camel}');
`;

const events = ({ pascal, camel, upper, corePath1 }) => `const eventBus = require('${corePath1}/eventBus');

const ${upper}_EVENTS = {
  CREATED: '${camel}.created',
  UPDATED: '${camel}.updated',
  DELETED: '${camel}.deleted',
};

function publish${pascal}Created(entity) {
  eventBus.publish(${upper}_EVENTS.CREATED, { id: entity._id });
}

function publish${pascal}Updated(entity) {
  eventBus.publish(${upper}_EVENTS.UPDATED, { id: entity._id });
}

function publish${pascal}Deleted(id) {
  eventBus.publish(${upper}_EVENTS.DELETED, { id });
}

module.exports = {
  ${upper}_EVENTS,
  publish${pascal}Created,
  publish${pascal}Updated,
  publish${pascal}Deleted,
};
`;

const service = ({ pascal, camel, corePath2 }) => `const ${camel}Repo = require('../../domain/repositories/${camel}.repository');
const ${camel}Cache = require('../../cache/${camel}.cache');
const {
  publish${pascal}Created,
  publish${pascal}Updated,
  publish${pascal}Deleted,
} = require('../../events/${camel}.events');
const ApiError = require('${corePath2}/ApiError');

class ${pascal}Service {
  async create(data) {
    const entity = await ${camel}Repo.create(data);
    await ${camel}Cache.flushNamespace();
    publish${pascal}Created(entity);
    return entity;
  }

  async getById(id) {
    return ${camel}Cache.remember(\`id:\${id}\`, 120, async () => {
      const entity = await ${camel}Repo.findById(id);
      if (!entity) throw ApiError.notFound('${pascal} not found');
      return entity;
    });
  }

  async list(filters = {}, options = {}) {
    const cacheKey = \`list:\${JSON.stringify(filters)}:\${JSON.stringify(options)}\`;
    return ${camel}Cache.remember(cacheKey, 60, () => ${camel}Repo.find(filters, options));
  }

  async update(id, updates) {
    const entity = await ${camel}Repo.updateById(id, updates);
    if (!entity) throw ApiError.notFound('${pascal} not found');
    await ${camel}Cache.forget(\`id:\${id}\`);
    await ${camel}Cache.flushNamespace();
    publish${pascal}Updated(entity);
    return entity;
  }

  async remove(id) {
    const entity = await ${camel}Repo.deleteById(id);
    if (!entity) throw ApiError.notFound('${pascal} not found');
    await ${camel}Cache.forget(\`id:\${id}\`);
    await ${camel}Cache.flushNamespace();
    publish${pascal}Deleted(id);
    return entity;
  }
}

module.exports = new ${pascal}Service();
`;

const validator = ({ pascal, corePath2 }) => `const { z } = require('zod');
const ApiError = require('${corePath2}/ApiError');

const createSchema = z.object({
  name: z.string().min(2).max(200),
  // TODO: add ${pascal}-specific fields
});

const updateSchema = createSchema.partial();

function validate(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return next(ApiError.badRequest('Validation failed', result.error.flatten()));
    }
    req.body = result.data;
    next();
  };
}

module.exports = {
  validateCreate: validate(createSchema),
  validateUpdate: validate(updateSchema),
};
`;

const controller = ({ camel, corePath2 }) => `const ${camel}Service = require('../../application/services/${camel}.service');
const catchAsync = require('${corePath2}/catchAsync');

exports.create = catchAsync(async (req, res) => {
  const entity = await ${camel}Service.create(req.body);
  res.status(201).json({ success: true, data: entity });
});

exports.getOne = catchAsync(async (req, res) => {
  const entity = await ${camel}Service.getById(req.params.id);
  res.json({ success: true, data: entity });
});

exports.list = catchAsync(async (req, res) => {
  const { page, limit, sort } = req.query;
  const result = await ${camel}Service.list({}, { page, limit, sort });
  res.json({ success: true, ...result });
});

exports.update = catchAsync(async (req, res) => {
  const entity = await ${camel}Service.update(req.params.id, req.body);
  res.json({ success: true, data: entity });
});

exports.remove = catchAsync(async (req, res) => {
  await ${camel}Service.remove(req.params.id);
  res.status(204).send();
});
`;

const routes = ({ camel }) => `const express = require('express');
const router = express.Router();

const controller = require('../controllers/${camel}.controller');
const { validateCreate, validateUpdate } = require('../validators/${camel}.validator');

router.get('/', controller.list);
router.get('/:id', controller.getOne);
router.post('/', validateCreate, controller.create);
router.patch('/:id', validateUpdate, controller.update);
router.delete('/:id', controller.remove);

module.exports = router;
`;

const moduleIndex = ({ camel, upper }) => `const router = require('./api/routes/${camel}.routes');
const ${camel}Service = require('./application/services/${camel}.service');
const { ${upper}_EVENTS } = require('./events/${camel}.events');

module.exports = {
  router,
  service: ${camel}Service,
  events: ${upper}_EVENTS,
};
`;

/**
 * Aggregator index.js for a PARENT namespace (e.g. src/modules/hrms/index.js).
 * Mounts each sub-module's router under its own path segment.
 * `children` = array of camelCase sub-module names already generated under this parent.
 */
const parentAggregatorIndex = (children) => {
  const toKebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();

  const requires = children
    .map((c) => `router.use('/${toKebab(c)}', require('./${c}').router);`)
    .join('\n');

  return `const express = require('express');
const router = express.Router();

/**
 * This is a NAMESPACE, not a module with its own model/service.
 * It only aggregates its sub-modules' routers below. Each one is a
 * fully independent module with its own model, repository, service,
 * events and cache — they do NOT import each other directly, only
 * communicate via the event bus.
 */
${requires}

module.exports = { router };
`;
};

module.exports = {
  model,
  repository,
  cache,
  events,
  service,
  validator,
  controller,
  routes,
  moduleIndex,
  parentAggregatorIndex,
};
APEX_EOF_MARKER

