class ApiError extends Error {
  constructor(statusCode, message, details = null) {
    super(message);
    this.statusCode = statusCode;
    this.details = details;
    this.isOperational = true; // distinguishes expected errors from bugs
    Error.captureStackTrace(this, this.constructor);
  }

  static badRequest(message, details) {
    return new ApiError(400, message, details);
  }

  static unauthorized(message = 'Unauthorized') {
    return new ApiError(401, message);
  }

  static forbidden(message = 'Forbidden') {
    return new ApiError(403, message);
  }

  static notFound(message = 'Not found') {
    return new ApiError(404, message);
  }

  static conflict(message) {
    return new ApiError(409, message);
  }

  static internal(message = 'Internal server error') {
    return new ApiError(500, message);
  }
}

module.exports = ApiError;
APEX_EOF_MARKER

cat > 'src/core/BaseRepository.js' << 'APEX_EOF_MARKER'
/**
 * Base repository every module repository can extend.
 * This is where "queries/commands" live in a lightweight form —
 * without splitting into a dozen tiny files. Add module-specific
 * methods in the subclass (e.g. findBySku, findLowStock).
 */
class BaseRepository {
  constructor(model) {
    this.model = model;
  }

  async create(data) {
    return this.model.create(data);
  }

  async findById(id) {
    return this.model.findById(id);
  }

  async findOne(filter) {
    return this.model.findOne(filter);
  }

  async find(filter = {}, { page = 1, limit = 20, sort = '-createdAt' } = {}) {
    const skip = (page - 1) * limit;
    const [data, total] = await Promise.all([
      this.model.find(filter).sort(sort).skip(skip).limit(limit),
      this.model.countDocuments(filter),
    ]);
    return { data, total, page: Number(page), limit: Number(limit) };
  }

  async updateById(id, updates) {
    return this.model.findByIdAndUpdate(id, updates, { new: true, runValidators: true });
  }

  async deleteById(id) {
    return this.model.findByIdAndDelete(id);
  }

  async exists(filter) {
    return this.model.exists(filter);
  }
}

module.exports = BaseRepository;
APEX_EOF_MARKER

cat > 'src/core/cache.js' << 'APEX_EOF_MARKER'
const redis = require('./redisClient');

/**
 * Thin, opinionated wrapper around Redis.
 * Modules should NEVER call redis.get/set directly — always go through this,
 * so caching strategy (prefixing, serialization, locking) lives in one place.
 */
class CacheService {
  constructor(namespace) {
    // e.g. new CacheService('products') -> keys are prefixed "cache:products:*"
    this.namespace = namespace;
  }

  _key(key) {
    return `cache:${this.namespace}:${key}`;
  }

  async get(key) {
    const raw = await redis.get(this._key(key));
    return raw ? JSON.parse(raw) : null;
  }

  async set(key, value, ttlSeconds = 300) {
    await redis.set(this._key(key), JSON.stringify(value), 'EX', ttlSeconds);
  }

  async forget(key) {
    await redis.del(this._key(key));
  }

  /**
   * Cache-aside helper: return cached value, or compute + cache it.
   *   const products = await cache.remember('list:active', 60, () => repo.findActive());
   */
  async remember(key, ttlSeconds, computeFn) {
    const cached = await this.get(key);
    if (cached !== null) return cached;
    const fresh = await computeFn();
    await this.set(key, fresh, ttlSeconds);
    return fresh;
  }

  /**
   * Invalidate every key under this namespace (e.g. after a bulk write).
   * Use sparingly — SCAN-based, not instant on huge keyspaces.
   */
  async flushNamespace() {
    const stream = redis.scanStream({ match: this._key('*') });
    const pipeline = redis.pipeline();
    let count = 0;
    for await (const keys of stream) {
      keys.forEach((k) => {
        pipeline.del(k);
        count += 1;
      });
    }
    if (count) await pipeline.exec();
  }

  /**
   * Simple distributed lock (e.g. to prevent double-processing a webhook).
   * Returns true if lock acquired.
   */
  async lock(key, ttlSeconds = 10) {
    const result = await redis.set(this._key(`lock:${key}`), '1', 'NX', 'EX', ttlSeconds);
    return result === 'OK';
  }

  async release(key) {
    await redis.del(this._key(`lock:${key}`));
  }
}

module.exports = CacheService;
APEX_EOF_MARKER

