cat > 'src/core/database.js' << 'APEX_EOF_MARKER'
const mongoose = require('mongoose');

const connections = {};

/**
 * Get (or lazily create) a mongoose connection for a given logical database.
 *
 * Usage inside a module's model file:
 *   const { getConnection } = require('../../../core/database');
 *   const conn = getConnection('products_db');
 *   module.exports = conn.model('Product', schema);
 *
 * All modules can share ONE physical MongoDB deployment while still being
 * logically separated by database name. This means when a module is
 * eventually extracted into its own service, its data comes with it —
 * no migration needed, no cross-module joins to untangle.
 *
 * If you don't need per-module DB isolation yet, just call
 * getConnection('main') everywhere — it's still a single connection.
 */
function getConnection(dbName = 'main') {
  if (connections[dbName]) return connections[dbName];

  const baseUri = process.env.MONGO_URI || 'mongodb://localhost:27017';
  const uri = baseUri.endsWith('/') ? `${baseUri}${dbName}` : `${baseUri}/${dbName}`;

  const conn = mongoose.createConnection(uri, {
    maxPoolSize: 10,
  });

  conn.on('connected', () => console.log(`[mongo] connected -> ${dbName}`));
  conn.on('error', (err) => console.error(`[mongo] error on ${dbName}:`, err.message));

  connections[dbName] = conn;
  return conn;
}

async function closeAll() {
  await Promise.all(Object.values(connections).map((c) => c.close()));
}

module.exports = { getConnection, closeAll };
APEX_EOF_MARKER

cat > 'src/core/errorHandler.js' << 'APEX_EOF_MARKER'
const ApiError = require('./ApiError');

function notFoundHandler(req, res, next) {
  next(ApiError.notFound(`Route not found: ${req.method} ${req.originalUrl}`));
}

// eslint-disable-next-line no-unused-vars
function errorHandler(err, req, res, next) {
  let error = err;

  // Convert known Mongoose errors into clean ApiErrors
  if (err.name === 'ValidationError') {
    error = ApiError.badRequest('Validation failed', err.errors);
  } else if (err.name === 'CastError') {
    error = ApiError.badRequest(`Invalid ${err.path}: ${err.value}`);
  } else if (err.code === 11000) {
    error = ApiError.conflict('Duplicate value violates a unique constraint');
  } else if (!(err instanceof ApiError)) {
    error = ApiError.internal(
      process.env.NODE_ENV === 'production' ? 'Something went wrong' : err.message
    );
  }

  if (!error.isOperational) {
    // eslint-disable-next-line no-console
    console.error('[unexpected error]', err);
  }

  res.status(error.statusCode).json({
    success: false,
    message: error.message,
    details: error.details || undefined,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });
}

module.exports = { notFoundHandler, errorHandler };
APEX_EOF_MARKER

cat > 'src/core/eventBus.js' << 'APEX_EOF_MARKER'
/**
 * In-process event bus.
 *
 * This is THE most important file in the whole framework.
 * Modules must NEVER import each other's services directly.
 * They only talk through events (or through a module's public index.js).
 *
 * Why this matters: when you eventually pull a module out into its own
 * service, you swap `eventBus.emit(...)` for a real message broker
 * publish (RabbitMQ/Kafka/SQS) and nothing inside the module has to change.
 */
const EventEmitter = require('events');

class AppEventBus extends EventEmitter {
  constructor() {
    super();
    this.setMaxListeners(50); // many modules may listen to the same event
  }

  /**
   * Emit an event and log it (useful for debugging cross-module flows).
   */
  publish(eventName, payload = {}) {
    if (process.env.EVENT_DEBUG === 'true') {
      // eslint-disable-next-line no-console
      console.log(`[event] ${eventName}`, payload);
    }
    this.emit(eventName, payload);
  }

  /**
   * Subscribe. Wrapped so we can later add retry/dead-letter logic
   * without touching every module's listener code.
   */
  subscribe(eventName, handler) {
    this.on(eventName, async (payload) => {
      try {
        await handler(payload);
      } catch (err) {
        // eslint-disable-next-line no-console
