const { z } = require('zod');
const ApiError = require('../../../../../core/ApiError');

const createSchema = z.object({
  name: z.string().min(2).max(200),
  // TODO: add StorefrontCustomer-specific fields
});

const updateSchema = createSchema.partial();

function validate(schema) {
