require('dotenv').config();
const { Worker } = require('bullmq');

const connection = {
  host: process.env.REDIS_HOST || 'localhost',
  port: process.env.REDIS_PORT || 6379,
};

const worker = new Worker(
  'products',
  async (job) => {
    if (job.name === 'reindex') {
      console.log(`[worker:products] reindexing product ${job.data.productId}`);
      // TODO: push to Elasticsearch / Algolia / whatever search backend
    }
  },
  { connection }
);

worker.on('completed', (job) => console.log(`[worker:products] job ${job.id} done`));
worker.on('failed', (job, err) => console.error(`[worker:products] job ${job.id} failed:`, err.message));

console.log('[worker:products] listening for jobs...');
APEX_EOF_MARKER

chmod +x scripts/make-module.js 2>/dev/null || true

echo ""
echo "Apex Framework project created successfully."
echo ""
echo "Next steps:"
echo "  1. cp .env.example .env"
echo "  2. npm install"
echo "  3. docker compose up -d mongo redis   (requires Docker)"
echo "  4. npm run dev"
echo ""
echo "Generate a new module any time with:"
echo "  npm run make:module -- <name>            (flat module)"
echo "  npm run make:module -- hrms/attendance   (nested sub-module)"
